<?php
namespace App\Services;
use App\Models\Ingredient;use App\Models\StockAdjustment;use App\Models\StockAdjustmentItem;use App\Models\StockBalance;use Illuminate\Contracts\Pagination\LengthAwarePaginator;use Illuminate\Database\Eloquent\Builder;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
class StockAdjustmentItemService
{
 public function getAll(?string $s=null,?int $id=null):LengthAwarePaginator{return StockAdjustmentItem::query()->with(['stockAdjustment.stockLocation','ingredient.baseUnit'])->when($id,fn(Builder $q)=>$q->where('stock_adjustment_id',$id))->when($s,fn(Builder $q)=>$q->whereHas('ingredient',fn(Builder $i)=>$i->where('name','like',"%$s%")->orWhere('code','like',"%$s%")))->orderByDesc('stock_adjustment_id')->orderBy('id')->paginate(15)->withQueryString();}
 public function options():array{return ['adjustments'=>StockAdjustment::query()->where('status','draft')->with('stockLocation')->orderByDesc('adjustment_date')->get(),'ingredients'=>Ingredient::query()->with('baseUnit')->orderBy('name')->get(['id','code','name','base_unit_id'])];}
 public function create(array $d):StockAdjustmentItem{return DB::transaction(function()use($d):StockAdjustmentItem{$a=StockAdjustment::query()->whereKey($d['stock_adjustment_id'])->lockForUpdate()->firstOrFail();$this->draft($a);$this->unique($a,(int)$d['ingredient_id']);$b=StockBalance::query()->where('ingredient_id',$d['ingredient_id'])->where('stock_location_id',$a->stock_location_id)->first();$current=(float)($b?->quantity_on_hand??0);return $a->items()->create(['ingredient_id'=>$d['ingredient_id'],'previous_quantity'=>$current,'adjusted_quantity'=>$d['adjusted_quantity'],'difference_quantity'=>round((float)$d['adjusted_quantity']-$current,3),'unit_cost'=>$b?->average_unit_cost??0]);});}
 public function update(StockAdjustmentItem $item,array $d):StockAdjustmentItem{return DB::transaction(function()use($item,$d):StockAdjustmentItem{$old=StockAdjustment::query()->whereKey($item->stock_adjustment_id)->lockForUpdate()->firstOrFail();$a=StockAdjustment::query()->whereKey($d['stock_adjustment_id'])->lockForUpdate()->firstOrFail();$this->draft($old);$this->draft($a);$this->unique($a,(int)$d['ingredient_id'],$item->id);$b=StockBalance::query()->where('ingredient_id',$d['ingredient_id'])->where('stock_location_id',$a->stock_location_id)->first();$current=(float)($b?->quantity_on_hand??0);$item->update(['stock_adjustment_id'=>$a->id,'ingredient_id'=>$d['ingredient_id'],'previous_quantity'=>$current,'adjusted_quantity'=>$d['adjusted_quantity'],'difference_quantity'=>round((float)$d['adjusted_quantity']-$current,3),'unit_cost'=>$b?->average_unit_cost??0]);return $item->refresh();});}
 public function delete(StockAdjustmentItem $item):bool{return DB::transaction(function()use($item):bool{$a=StockAdjustment::query()->whereKey($item->stock_adjustment_id)->lockForUpdate()->firstOrFail();return $a->status==='draft'&&(bool)$item->delete();});}
 private function unique(StockAdjustment $a,int $ingredient,?int $except=null):void{if($a->items()->where('ingredient_id',$ingredient)->when($except,fn(Builder $q)=>$q->where('id','!=',$except))->exists())throw ValidationException::withMessages(['ingredient_id'=>'This ingredient is already in the adjustment.']);}
 private function draft(StockAdjustment $a):void{if($a->status!=='draft')throw ValidationException::withMessages(['stock_adjustment_id'=>'Adjustment lines can only be changed while the adjustment is a draft.']);}
}
